/*
 * Hand-written rather than generated by a plugin: PWA plugins reliably lag
 * Next.js major versions, and this worker is small enough to own.
 *
 * Bump CACHE_VERSION to invalidate everything.
 */
const CACHE_VERSION = 'alice-may-v1'
const OFFLINE_URL = '/offline'

const PRECACHE = [OFFLINE_URL, '/icons/icon-192.png', '/icons/icon-512.png']

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE_VERSION)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CACHE_VERSION).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  )
})

/**
 * Never cache auth or API traffic, and never cache a non-GET request.
 * Caching an auth response is how a service worker serves one person's
 * session to somebody else.
 */
function isCacheable(request) {
  if (request.method !== 'GET') return false

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return false
  if (url.pathname.startsWith('/auth/')) return false
  if (url.pathname.startsWith('/api/')) return false
  if (url.pathname.startsWith('/fp/')) return false

  return true
}

self.addEventListener('fetch', (event) => {
  const { request } = event

  if (!isCacheable(request)) return

  // Navigations: network first, falling back to the offline page.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(async () => {
        const cache = await caches.open(CACHE_VERSION)
        return (await cache.match(request)) ?? (await cache.match(OFFLINE_URL))
      }),
    )
    return
  }

  // Static assets: cache first, refreshing in the background.
  if (
    request.destination === 'style' ||
    request.destination === 'script' ||
    request.destination === 'font' ||
    request.destination === 'image'
  ) {
    event.respondWith(
      caches.open(CACHE_VERSION).then(async (cache) => {
        const cached = await cache.match(request)
        const network = fetch(request)
          .then((response) => {
            if (response.ok) cache.put(request, response.clone())
            return response
          })
          .catch(() => cached)
        return cached ?? network
      }),
    )
  }
})
